mapper.select:
SELECT f.id, f.biz_type, f.doc_id, f.doc_no, f.warehouse_id, w.name AS warehouse_name, f.location_id,
       l.code AS location_code, f.material_id, m.code AS material_code, m.name AS material_name, m.spec, m.unit,
       f.batch_no, f.qty, f.biz_price, f.cost_price, f.cost_amount, f.partner_id, f.partner_name,
       f.cost_estimated, sd.biz_type AS doc_biz_type, u.nickname AS create_by_name, f.create_time
FROM wms_stock_flow f
JOIN wms_material m ON m.id = f.material_id
JOIN wms_warehouse w ON w.id = f.warehouse_id
LEFT JOIN wms_location l ON l.id = f.location_id
LEFT JOIN wms_stock_doc sd ON f.biz_type IN ('IN', 'OUT') AND sd.id = f.doc_id
LEFT JOIN sys_user u ON u.id = f.create_by

    f.biz_type = #{q.bizType}
    AND f.warehouse_id = #{q.warehouseId}
    AND f.material_id = #{q.materialId}

        AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))

    AND f.batch_no = #{q.batchNo}
    AND f.doc_no = #{q.docNo}
    AND f.create_time >= #{begin}
    AND f.create_time < #{end}

ORDER BY f.id DESC

SELECT material_id AS "materialId", SUM(qty) AS "qty", SUM(cost_amount) AS "amount"
FROM wms_stock_flow
WHERE biz_type = #{kind}
  AND doc_id IN #{id}
  AND cost_amount IS NOT NULL
GROUP BY material_id

SELECT f.material_id AS "materialId", SUM(f.qty) AS "qty", SUM(f.cost_amount) AS "amount"
FROM wms_stock_flow f
JOIN wms_stock_doc sd ON sd.id = f.doc_id
WHERE f.biz_type = #{kind}
  AND sd.kind = #{kind}
  AND sd.biz_type = #{bizType}
  AND sd.source_no = #{sourceNo}
  AND f.cost_amount IS NOT NULL
GROUP BY f.material_id

SELECT id, material_id, qty, cost_price, cost_amount
FROM wms_stock_flow
WHERE biz_type = #{kind}
  AND doc_id = #{docId}
  AND material_id IN #{id}
  AND cost_amount IS NOT NULL
ORDER BY id

SELECT material_id AS "materialId", location_id AS "locationId", batch_no AS "batchNo", SUM(cost_amount) AS "amount"
FROM wms_stock_flow
WHERE biz_type = #{kind}
  AND doc_id = #{docId}
  AND cost_amount IS NOT NULL
GROUP BY material_id, location_id, batch_no

SELECT COALESCE(SUM(f.qty), 0) AS "qty", COALESCE(SUM(f.cost_amount), 0) AS "amount",
       COALESCE(MAX(f.cost_estimated), 0) AS "estimated"

AND  < #{q.beginDate}

SELECT f.id,  AS biz_date, f.biz_type, sd.biz_type AS doc_biz_type, f.doc_id, f.doc_no,
       sd.source_no, w.name AS warehouse_name, f.batch_no, f.qty, f.biz_price, f.cost_price, f.cost_amount,
       f.partner_name, f.cost_estimated, f.create_time

AND  >= #{q.beginDate} AND  <= #{q.endDate}
ORDER BY , f.id
LIMIT #{limit}
